package stepanel

import (
	"io/fs"
	"net/http"
	"os"
	"strings"
	"time"
)

// registerRoutes builds the HTTP surface separately from process startup.
// Keep route patterns and registration order here so routing policy can be
// reviewed and tested independently of initialization and recovery work.
func (a *App) registerRoutes(staticAssets fs.FS) *http.ServeMux {
	mux := http.NewServeMux()
	a.MetadataCache = NewMetadataCache(10 * time.Second) // 10-second TTL for metadata
	mux.Handle("/livez", allowMethods(http.HandlerFunc(a.livez), http.MethodGet, http.MethodHead))
	mux.Handle("/readyz", allowMethods(http.HandlerFunc(a.readyz), http.MethodGet, http.MethodHead))
	mux.Handle("/static/", allowMethods(http.StripPrefix("/static/", http.FileServer(http.FS(staticAssets))), http.MethodGet, http.MethodHead))
	mux.Handle("/login", allowMethods(http.HandlerFunc(a.Auth.Login), http.MethodGet, http.MethodPost))
	mux.Handle("/logout", allowMethods(http.HandlerFunc(a.Auth.Logout), http.MethodPost))
	mux.Handle("/", allowMethods(a.Auth.Require(http.HandlerFunc(a.dashboard)), http.MethodGet, http.MethodHead))
	mux.Handle("/panel", allowMethods(a.Auth.Require(http.HandlerFunc(a.customerPanel)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/health", allowMethods(http.HandlerFunc(a.health), http.MethodGet, http.MethodHead))
	mux.Handle("/api/health/operational", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.operationalHealth)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/capabilities", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.handleCapabilities)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/services", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.services)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/database", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.database)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/database/diagnostics", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.databaseDiagnostics)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/database/sessions", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.databaseSessions)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/database/sessions/", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.databaseSessionTerminate)), http.MethodDelete))
	mux.Handle("/api/database/settings", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.databaseSettings)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/databases", allowMethods(a.Auth.Require(http.HandlerFunc(a.databaseCollection)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/databases/{id}/deletion-preview", allowMethods(a.Auth.Require(http.HandlerFunc(a.databaseResource)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/databases/", allowMethods(a.Auth.Require(http.HandlerFunc(a.databaseResource)), http.MethodGet, http.MethodHead, http.MethodPatch, http.MethodDelete))
	mux.Handle("/api/ftp", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.ftpEndpoint)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/security/audit", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.securityAudit)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/security/audit/reconciliation", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.securityAuditReconciliation)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/security/center", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.securityCenter)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/audit/events", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.auditEvents)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/cloud", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.cloudInventory)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/cloud/action", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.cloudAction)), http.MethodPost))
	mux.Handle("/api/cloud/dns", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.cloudDNS)), http.MethodGet, http.MethodHead, http.MethodPost, http.MethodDelete))
	mux.Handle("/api/dns/capabilities", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.dnsCapabilities)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/cloud/loadbalancer", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.cloudLoadBalancer)), http.MethodPost))
	mux.Handle("/api/cloud/snapshots", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.cloudSnapshots)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/ssh", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.sshInventory)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/ssh/action", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.sshAction)), http.MethodPost))
	mux.Handle("/api/security/scan", allowMethods(a.Auth.RequireAdministrator(a.limitConcurrentResource(http.HandlerFunc(a.malwareScan), "malware_scan")), http.MethodPost))
	mux.Handle("/api/certificates/issue", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.issueCertificate)), http.MethodPost))
	mux.Handle("/api/certificates/preview", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.issueCertificate)), http.MethodPost))
	mux.Handle("/api/node/versions", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.nodeVersions)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/node/select", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.selectNode)), http.MethodPost))
	mux.Handle("/api/node/tooling", allowMethods(a.Auth.Require(a.siteOperation("node.tooling")), http.MethodPost))
	mux.Handle("/api/proxy/deploy", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.deployProxy)), http.MethodPost))
	mux.Handle("/api/proxy", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.proxyList)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/proxy/test", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.proxyTest)), http.MethodPost))
	mux.Handle("/api/proxy/", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.proxyManage)), http.MethodDelete))
	mux.Handle("/api/sites", allowMethods(a.Auth.Require(http.HandlerFunc(a.sites)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/sites/overview", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteOverviewList)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/overview/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteOverviewResource)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/recovery/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteRecovery)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/environment/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteEnvironment)), http.MethodGet, http.MethodPut, http.MethodDelete))
	mux.Handle("/api/sites/redis/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteRedis)), http.MethodGet, http.MethodPut, http.MethodDelete))
	mux.Handle("/api/sites/access/", allowMethods(a.Auth.Require(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodDelete {
			a.siteAccessKey(w, r)
			return
		}
		a.siteAccess(w, r)
	})), http.MethodGet, http.MethodPatch, http.MethodPost, http.MethodDelete))
	mux.Handle("/api/workers/", allowMethods(a.Auth.Require(http.HandlerFunc(a.workers)), http.MethodGet, http.MethodPut, http.MethodPost, http.MethodDelete))
	mux.Handle("/api/tasks/{site}/{name}/kill", allowMethods(a.Auth.Require(http.HandlerFunc(a.tasks)), http.MethodPost))
	mux.Handle("/api/tasks/", allowMethods(a.Auth.Require(http.HandlerFunc(a.tasks)), http.MethodGet, http.MethodPost, http.MethodPut, http.MethodDelete))
	mux.Handle("/api/python/deploy", allowMethods(a.Auth.Require(a.siteOperation("python.deploy")), http.MethodPost))
	mux.Handle("/api/python/", allowMethods(a.Auth.Require(http.HandlerFunc(a.pythonAction)), http.MethodPost))
	mux.Handle("/api/composer/", allowMethods(a.Auth.Require(a.siteOperation("composer.install")), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/sites/php/", allowMethods(a.Auth.Require(http.HandlerFunc(a.phpRuntime)), http.MethodGet, http.MethodHead, http.MethodPost, http.MethodPut))
	mux.Handle("/api/sites/resources/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteResources)), http.MethodGet, http.MethodHead, http.MethodPost, http.MethodPut))
	mux.Handle("/api/sites/usage/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteUsage)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/diagnostics/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteDiagnostics)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/files/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteFiles)), http.MethodGet, http.MethodHead, http.MethodPut, http.MethodPost))
	mux.Handle("/api/reconcile/resources", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.reconcileResources)), http.MethodPost))
	mux.Handle("/api/reconcile/tasks", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.reconcileTasksHTTP)), http.MethodPost))
	mux.Handle("/api/staging", allowMethods(a.Auth.Require(a.siteOperation("staging.create")), http.MethodPost))
	mux.Handle("/api/staging/promote/preview", allowMethods(a.Auth.Require(http.HandlerFunc(a.stagingPromotionPreview)), http.MethodPost))
	mux.Handle("/api/staging/promote", allowMethods(a.Auth.Require(a.siteOperation("staging.promote")), http.MethodPost))
	mux.Handle("/api/runner/build", allowMethods(a.Auth.Require(a.siteOperation("runner.build")), http.MethodPost))
	mux.Handle("/api/deployments", allowMethods(a.Auth.Require(http.HandlerFunc(a.deployments)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/deployments/run", allowMethods(a.Auth.Require(a.siteOperation("release.pipeline")), http.MethodPost))
	mux.Handle("/api/sites/logs/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteLogs)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/sites/deploy", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteDeploy)), http.MethodPost))
	mux.Handle("/api/sites/route-delete-preview", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteRouteDeletePreview)), http.MethodPost))
	mux.Handle("/api/sites/domains/claim", allowMethods(a.Auth.Require(http.HandlerFunc(a.domainClaim)), http.MethodPost))
	mux.Handle("/api/sites/domains/verify", allowMethods(a.Auth.Require(http.HandlerFunc(a.domainVerify)), http.MethodPost))
	mux.Handle("/api/sites/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteManage)), http.MethodDelete))
	mux.Handle("/api/sites/terminate", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.siteTermination)), http.MethodPost))
	mux.Handle("/api/backups", allowMethods(a.Auth.Require(http.HandlerFunc(a.backups)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/backups/rehearse", allowMethods(a.Auth.Require(http.HandlerFunc(a.backupRehearse)), http.MethodPost))
	mux.Handle("/api/backups/restore-to-staging", allowMethods(a.Auth.Require(a.siteOperation("backup.restore-to-staging")), http.MethodPost))
	mux.Handle("/api/backups/restore-offsite-to-staging", allowMethods(a.Auth.Require(a.siteOperation("backup.offsite-to-staging")), http.MethodPost))
	mux.Handle("/api/backups/restore-files", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.backupRestoreFilesHTTP)), http.MethodPost))
	mux.Handle("/api/backups/restore-database", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.backupRestoreDatabaseHTTP)), http.MethodPost))
	mux.Handle("/api/backups/restore-offsite-files", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.backupRestoreOffsiteFilesHTTP)), http.MethodPost))
	mux.Handle("/api/backups/restore-offsite-database", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.backupRestoreOffsiteDatabaseHTTP)), http.MethodPost))
	mux.Handle("/api/backups/verify", allowMethods(a.Auth.Require(http.HandlerFunc(a.backupVerify)), http.MethodPost))
	mux.Handle("/api/backup-schedules", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.backupSchedules)), http.MethodGet, http.MethodHead, http.MethodPut, http.MethodDelete))
	mux.Handle("/api/apps", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.appList)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/apps/deploy", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.appDeploy)), http.MethodPost))
	// Git deployment is a site-scoped customer operation. The operation
	// handler still enforces site ownership and the deploy:write scope before
	// queueing, while administrators retain access to every managed site.
	mux.Handle("/api/sites/git-deploy", allowMethods(a.Auth.Require(a.siteOperation("git.deploy")), http.MethodPost))
	mux.Handle("/api/sites/git-key/", allowMethods(a.Auth.Require(http.HandlerFunc(a.siteGitKey)), http.MethodGet, http.MethodHead, http.MethodPost, http.MethodDelete))
	// Webhook endpoint now includes site in path for per-site secret isolation.
	// Old endpoint /api/sites/git-webhook supported global secret only and is deprecated.
	mux.Handle("/api/sites/git-webhook/", allowMethods(http.HandlerFunc(a.gitWebhook), http.MethodPost))
	mux.Handle("/api/admin/webhooks/", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.webhookConfig)), http.MethodPost, http.MethodPut, http.MethodDelete))
	mux.Handle("/api/sites/git-rollback", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.gitRollback)), http.MethodPost))
	mux.Handle("/api/sites/git-rollback/preview", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.gitRollbackPreviewHandler)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/caddy/htaccess", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.htaccessMigration)), http.MethodPost))
	mux.Handle("/api/apps/", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.appAction)), http.MethodPost))
	mux.Handle("/api/cpmove/inspect", allowMethods(a.Auth.RequireAdministrator(a.limitConcurrentResource(http.HandlerFunc(a.inspect), "extract")), http.MethodPost))
	mux.Handle("/api/cpmove/import", allowMethods(a.Auth.RequireAdministrator(a.limitConcurrentResource(http.HandlerFunc(a.importBackup), "extract")), http.MethodPost))
	mux.Handle("/api/wpress/preflight", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.wpressPreflight)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/wpress/import", allowMethods(a.Auth.RequireAdministrator(a.limitConcurrentResource(http.HandlerFunc(a.wpressImport), "extract")), http.MethodPost))
	mux.Handle("/api/wordpress/status/", allowMethods(a.Auth.Require(http.HandlerFunc(a.wordpressStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/wordpress/", allowMethods(a.Auth.Require(http.HandlerFunc(a.wordpressAction)), http.MethodPost))
	mux.Handle("/api/accounts", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.accounts)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/accounts/", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.accounts)), http.MethodPatch, http.MethodDelete, http.MethodPost))
	mux.Handle("/api/admin/plan-status", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.accountPlanStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/suspend", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.accountSuspend)), http.MethodPost))
	mux.Handle("/api/admin/unsuspend", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.accountUnsuspend)), http.MethodPost))
	mux.Handle("/api/admin/migration-doctor", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.migrationDoctor)), http.MethodPost))
	mux.Handle("/api/admin/migration-doctor/status", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.migrationAnalysisStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/production-readiness", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.productionReadiness)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/support-bundle", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.supportBundle)), http.MethodGet))
	mux.Handle("/api/admin/resources/status", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.resourceStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/archive/inspect", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.inspectArchive)), http.MethodPost))
	mux.Handle("/api/admin/archive/inspect/status", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.inspectArchiveStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/archive/import", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.archiveImportStart)), http.MethodPost))
	mux.Handle("/api/admin/archive/import/status", allowMethods(a.Auth.RequireAdministrator(http.HandlerFunc(a.archiveImportStatus)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/account/password", allowMethods(a.Auth.Require(http.HandlerFunc(a.customerPassword)), http.MethodPost))
	mux.Handle("/api/account/mfa", allowMethods(a.Auth.Require(http.HandlerFunc(a.customerMFA)), http.MethodPost))
	mux.Handle("/api/account/sessions/revoke", allowMethods(a.Auth.Require(http.HandlerFunc(a.customerSessionsRevoke)), http.MethodPost))
	mux.Handle("/api/account/tokens", allowMethods(a.Auth.Require(http.HandlerFunc(a.apiTokens)), http.MethodGet, http.MethodPost))
	mux.Handle("/api/account/tokens/", allowMethods(a.Auth.Require(http.HandlerFunc(a.apiTokens)), http.MethodDelete))
	mux.Handle("/api/account/security", allowMethods(a.Auth.Require(http.HandlerFunc(a.customerSecurityCenter)), http.MethodGet))
	mux.Handle("/api/account/me", allowMethods(a.Auth.Require(http.HandlerFunc(a.accountMe)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/account/hosting", allowMethods(a.Auth.Require(http.HandlerFunc(a.accountHosting)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/account/members", allowMethods(a.Auth.Require(http.HandlerFunc(a.accountMembers)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/account/members/", allowMethods(a.Auth.Require(http.HandlerFunc(a.accountMembers)), http.MethodPatch, http.MethodDelete))
	mux.Handle("/api/account/activity", allowMethods(a.Auth.Require(http.HandlerFunc(a.accountActivity)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/admin/tokens", allowMethods(a.Auth.Require(http.HandlerFunc(a.adminAPITokens)), http.MethodGet, http.MethodPost))
	mux.Handle("/api/admin/tokens/", allowMethods(a.Auth.Require(http.HandlerFunc(a.adminAPITokens)), http.MethodDelete))
	mux.Handle("/api/jobs/", allowMethods(a.Auth.Require(http.HandlerFunc(a.jobStatus)), http.MethodGet, http.MethodHead, http.MethodPost))
	mux.Handle("/api/jobs", allowMethods(a.Auth.Require(http.HandlerFunc(a.jobList)), http.MethodGet, http.MethodHead))
	mux.Handle("/api/jobs/events", allowMethods(a.Auth.Require(http.HandlerFunc(a.jobEvents)), http.MethodGet, http.MethodHead))
	metricsHandler := http.Handler(http.HandlerFunc(a.metrics))
	if os.Getenv("STEPANEL_METRICS_PUBLIC") != "1" {
		metricsHandler = a.Auth.RequireAdministrator(metricsHandler)
	}
	mux.Handle("/metrics", allowMethods(metricsHandler, http.MethodGet, http.MethodHead))
	// /api/v1 is the stable automation namespace. The dashboard's existing
	// /api paths remain compatible and route to the same handlers and policies.
	mux.Handle("/api/v1/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("X-StePanel-API-Version", "v1")
		clone := r.Clone(r.Context())
		clone.Pattern = ""
		urlCopy := *r.URL
		urlCopy.Path = "/api" + strings.TrimPrefix(r.URL.Path, "/api/v1")
		urlCopy.RawPath = ""
		clone.URL = &urlCopy
		mux.ServeHTTP(w, clone)
	}))
	return mux
}
